PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, display_name TEXT NOT NULL, plan TEXT NOT NULL DEFAULT 'free', storage_limit INTEGER, created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS campaigns(id TEXT PRIMARY KEY, owner INTEGER NOT NULL REFERENCES users(id), name TEXT NOT NULL, objective TEXT NOT NULL, timezone TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','active','paused','cancelled','completed')), version INTEGER NOT NULL DEFAULT 1, approved_version INTEGER, rights_confirmed INTEGER NOT NULL DEFAULT 0, destination TEXT NOT NULL DEFAULT '', created_at REAL NOT NULL, updated_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS members(campaign TEXT REFERENCES campaigns(id), user_id INTEGER NOT NULL, role TEXT NOT NULL CHECK(role IN ('manager','editor','reviewer','viewer')), PRIMARY KEY(campaign,user_id));
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY, owner INTEGER NOT NULL REFERENCES users(id), platform TEXT NOT NULL, external_id TEXT NOT NULL, handle TEXT NOT NULL, scope TEXT NOT NULL CHECK(scope IN ('own','tdf')), credentials TEXT NOT NULL, permissions TEXT NOT NULL, expires_at REAL, revoked INTEGER NOT NULL DEFAULT 0, UNIQUE(platform,external_id));
CREATE TABLE IF NOT EXISTS pieces(id TEXT PRIMARY KEY, campaign TEXT NOT NULL REFERENCES campaigns(id), name TEXT NOT NULL, platform TEXT NOT NULL, format TEXT NOT NULL, account TEXT REFERENCES accounts(id), copy TEXT NOT NULL, asset TEXT, destination TEXT NOT NULL, due_at REAL NOT NULL, late_seconds INTEGER NOT NULL DEFAULT 3600, version INTEGER NOT NULL DEFAULT 1, approved_version INTEGER, tdf_approval_version INTEGER, dm_approval_version INTEGER, recipient TEXT, settings TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'draft', external_id TEXT, public_url TEXT, verified_at REAL, created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY, owner INTEGER NOT NULL REFERENCES users(id), campaign TEXT REFERENCES campaigns(id), name TEXT NOT NULL, path TEXT NOT NULL UNIQUE, size INTEGER NOT NULL DEFAULT 0, reserved INTEGER NOT NULL, uploaded INTEGER NOT NULL DEFAULT 0, sha256 TEXT, status TEXT NOT NULL DEFAULT 'uploading', original INTEGER NOT NULL DEFAULT 0, created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, campaign TEXT REFERENCES campaigns(id), piece TEXT REFERENCES pieces(id), kind TEXT NOT NULL, payload TEXT NOT NULL, due_at REAL NOT NULL, state TEXT NOT NULL DEFAULT 'queued', attempts INTEGER NOT NULL DEFAULT 0, claimed_at REAL, finished_at REAL, error TEXT, UNIQUE(piece,kind));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT, campaign TEXT, actor INTEGER, action TEXT NOT NULL, subject TEXT, at REAL NOT NULL, details TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notices(id TEXT PRIMARY KEY, owner INTEGER NOT NULL, campaign TEXT, severity TEXT NOT NULL, message TEXT NOT NULL, created_at REAL NOT NULL, read_at REAL, delivered TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS metrics(id TEXT PRIMARY KEY, campaign TEXT NOT NULL, piece TEXT, at REAL NOT NULL, data TEXT NOT NULL, UNIQUE(piece,at));
CREATE TABLE IF NOT EXISTS oauth_states(state TEXT PRIMARY KEY, owner INTEGER NOT NULL, platform TEXT NOT NULL, scope TEXT NOT NULL, verifier TEXT NOT NULL, expires_at REAL NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS notification_preferences(owner INTEGER PRIMARY KEY, email TEXT, push_subscription TEXT, webhook_url TEXT, channels TEXT NOT NULL DEFAULT '["in_app"]');
CREATE TABLE IF NOT EXISTS usage(owner INTEGER NOT NULL, month TEXT NOT NULL, render_seconds REAL NOT NULL DEFAULT 0, PRIMARY KEY(owner,month));
CREATE TABLE IF NOT EXISTS heartbeat(name TEXT PRIMARY KEY, at REAL NOT NULL, details TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS imports(key TEXT PRIMARY KEY, imported_at REAL NOT NULL, digest TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_sessions(piece TEXT PRIMARY KEY REFERENCES pieces(id), payload TEXT NOT NULL, updated_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS backup_settings(id INTEGER PRIMARY KEY CHECK(id=1),owner INTEGER NOT NULL REFERENCES users(id),account TEXT REFERENCES accounts(id),folder_id TEXT,public_key TEXT,fingerprint TEXT,key_confirmed_at REAL,enabled INTEGER NOT NULL DEFAULT 0,last_completed_at REAL,challenge TEXT,challenge_expires_at REAL);
CREATE TABLE IF NOT EXISTS backup_objects(id TEXT PRIMARY KEY,account TEXT NOT NULL REFERENCES accounts(id),folder_id TEXT NOT NULL,source_sha256 TEXT NOT NULL,source_size INTEGER NOT NULL,recipient TEXT NOT NULL,cipher_size INTEGER NOT NULL DEFAULT 0,upload_state TEXT,remote_id TEXT,verified_at REAL,updated_at REAL NOT NULL,UNIQUE(account,folder_id,source_sha256,source_size,recipient));
CREATE TABLE IF NOT EXISTS backup_requests(id TEXT PRIMARY KEY,owner INTEGER NOT NULL,requested_at REAL NOT NULL,state TEXT NOT NULL DEFAULT 'queued',started_at REAL,finished_at REAL,error TEXT,manifest_id TEXT);
